-- SAMPLE DATA: Nile Petroleum (NILPET1), South Sudan -- 10 more departments, 40 designations, 100 employees with their job
-- records, reporting lines, department heads and login accounts.
-- DEVELOPMENT DATABASES ONLY. It creates 100 working logins that share one temporary password and must change it at first
-- sign-in. Do not run this on a production database.
-- Run AFTER V8 and db/seed_nilepet_south_sudan_branches.sql, as the HRMS user. Safe to run twice: a row that exists is skipped.
-- Existing rows are never changed, except that departments WITHOUT a head get one (see the end).
-- Undo: db/seed_nilepet_departments_employees_rollback.sql
--
-- What it creates
--   departments  HSE, RETAIL, DEPOT, SCM, ENGMNT, TRADE, AUDIT, COMMS, SEC, FLEET
--   employees    100 (EMP-2026-nnnn, work e-mail first.last@nilepet.com): names in English and Arabic, date of birth, gender,
--                blood group, marital status, nationality, religion, personal e-mail and phone, work phone for managers, hire date,
--                probation or confirmation dates (12 recent hires are on probation), employment type, status
--   job records  one current row each: department, designation, reporting manager, office location, BRANCH, shift, work mode
--                (8 employees are left WITHOUT a branch on purpose so the Branch Assignments screen has rows to work on)
--   logins       roles: 1 HR_ADMIN, 2 HR_MANAGER, 97 EMPLOYEE (department heads are ordinary employees; the app treats them as
--                heads through the department head setting). Username = the part of the work e-mail before @.
-- Arabic text uses UNISTR escapes so it loads correctly whatever the client encoding is.

-- ===== 1. Departments =====
INSERT INTO HRMS.DEPARTMENTS (DEPT_ID, CODE, NAME, NAME_AR, DESCRIPTION, COST_CENTER_CODE, IS_ACTIVE)
